func collectedLengths(_ words: [String]) async -> [Int] {
    return await withTaskGroup(of: Int.self, returning: [Int].self) { group in
        for word in words {
            group.addTask {
                word.count
            }
        }
        var lengths: [Int] = []
        for await length in group {
            lengths.append(length)
        }
        return lengths.sorted()
    }
}
print(await collectedLengths(["map", "a", "sun"]))
```
